From fac090e31732e3abeb32dccc6b50da7f6559ecfb Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 02:18:11 +0100
Subject: [PATCH] plasmashell: Send layer shell surfaces their position

Plasma places panel popups and tooltips from where it thinks the panel
is, but only KWin knows where layer shell surfaces end up, for example
below other panels. Send them their position through the plasma surface.

CCBUG: 518087
---
 src/layershellv1window.cpp  | 14 ++++++++++++++
 src/layershellv1window.h    |  3 +++
 src/wayland/plasmashell.cpp |  9 ++++++++-
 src/wayland/plasmashell.h   |  6 ++++++
 src/wayland_server.cpp      | 13 ++++++++++++-
 src/wayland_server.h        |  1 +
 6 files changed, 44 insertions(+), 2 deletions(-)

diff --git a/src/layershellv1window.cpp b/src/layershellv1window.cpp
index bee106ff1b..3635510fcd 100644
--- a/src/layershellv1window.cpp
+++ b/src/layershellv1window.cpp
@@ -11,6 +11,7 @@
 #include "screenedge.h"
 #include "wayland/layershell_v1.h"
 #include "wayland/output.h"
+#include "wayland/plasmashell.h"
 #include "wayland/screenedge_v1.h"
 #include "wayland/surface.h"
 #include "wayland_server.h"
@@ -364,6 +365,19 @@ void LayerShellV1Window::installAutoHideScreenEdgeV1(AutoHideScreenEdgeV1Interfa
     });
 }

+void LayerShellV1Window::installPlasmaShellSurface(PlasmaShellSurfaceInterface *shellSurface)
+{
+    m_plasmaShellSurface = shellSurface;
+
+    auto sendPosition = [this]() {
+        m_plasmaShellSurface->sendPosition(pos().toPoint());
+    };
+    connect(this, &LayerShellV1Window::frameGeometryChanged, shellSurface, sendPosition);
+    if (isShown()) {
+        sendPosition();
+    }
+}
+
 void LayerShellV1Window::reserveScreenEdge()
 {
     if (workspace()->screenEdges()->reserve(this, m_screenEdge->border())) {
diff --git a/src/layershellv1window.h b/src/layershellv1window.h
index 9f7a6e1d64..54a5c511ef 100644
--- a/src/layershellv1window.h
+++ b/src/layershellv1window.h
@@ -19,6 +19,7 @@ struct LayerShellV1ConfigureEvent

 class AutoHideScreenEdgeV1Interface;
 class LayerSurfaceV1Interface;
+class PlasmaShellSurfaceInterface;
 class LogicalOutput;
 class LayerShellV1Integration;

@@ -49,6 +50,7 @@ public:
     void showOnScreenEdge() override;

     void installAutoHideScreenEdgeV1(AutoHideScreenEdgeV1Interface *edge);
+    void installPlasmaShellSurface(PlasmaShellSurfaceInterface *shellSurface);

 protected:
     Layer belongsToLayer() const override;
@@ -75,6 +77,7 @@ private:
     LayerShellV1Integration *m_integration;
     LayerSurfaceV1Interface *m_shellSurface;
     QPointer<AutoHideScreenEdgeV1Interface> m_screenEdge;
+    QPointer<PlasmaShellSurfaceInterface> m_plasmaShellSurface;
     bool m_screenEdgeActive = false;
     WindowType m_windowType;
     QList<LayerShellV1ConfigureEvent> m_configureEvents;
diff --git a/src/wayland/plasmashell.cpp b/src/wayland/plasmashell.cpp
index 51d34a5755..8b4f9a1bd6 100644
--- a/src/wayland/plasmashell.cpp
+++ b/src/wayland/plasmashell.cpp
@@ -16,7 +16,7 @@
 namespace KWin
 {

-static const quint32 s_version = 8;
+static const quint32 s_version = 9;
 static QList<PlasmaShellSurfaceInterface *> s_shellSurfaces;

 class PlasmaShellSurfaceCommit : public SurfaceAttachedState<PlasmaShellSurfaceCommit>
@@ -323,6 +323,13 @@ void PlasmaShellSurfaceInterface::showAutoHidingPanel()
     d->send_auto_hidden_panel_shown();
 }

+void PlasmaShellSurfaceInterface::sendPosition(const QPoint &position)
+{
+    if (d->resource()->version() >= ORG_KDE_PLASMA_SURFACE_POSITION_SINCE_VERSION) {
+        d->send_position(position.x(), position.y());
+    }
+}
+
 bool PlasmaShellSurfaceInterface::panelTakesFocus() const
 {
     return d->m_panelTakesFocus;
diff --git a/src/wayland/plasmashell.h b/src/wayland/plasmashell.h
index d62d3272b8..6143eba132 100644
--- a/src/wayland/plasmashell.h
+++ b/src/wayland/plasmashell.h
@@ -151,6 +151,12 @@ public:
      */
     void showAutoHidingPanel();

+    /**
+     * Tells the client the global position of a surface that the compositor places itself,
+     * such as a layer shell surface.
+     */
+    void sendPosition(const QPoint &position);
+
     /**
      * Whether a PlasmaShellSurfaceInterface wants to have focus.
      *
diff --git a/src/wayland_server.cpp b/src/wayland_server.cpp
index e83c6adcb8..7a9f267a07 100644
--- a/src/wayland_server.cpp
+++ b/src/wayland_server.cpp
@@ -253,6 +253,15 @@ void WaylandServer::registerXdgToplevelWindow(XdgToplevelWindow *window)
     });
 }

+void WaylandServer::registerLayerShellWindow(Window *window)
+{
+    registerWindow(window);
+
+    if (auto shellSurface = PlasmaShellSurfaceInterface::get(window->surface())) {
+        static_cast<LayerShellV1Window *>(window)->installPlasmaShellSurface(shellSurface);
+    }
+}
+
 void WaylandServer::registerXdgGenericWindow(Window *window)
 {
     if (auto toplevel = qobject_cast<XdgToplevelWindow *>(window)) {
@@ -384,6 +393,8 @@ bool WaylandServer::init()
     connect(m_plasmaShell, &PlasmaShellInterface::surfaceCreated, this, [this](PlasmaShellSurfaceInterface *surface) {
         if (XdgToplevelWindow *window = findXdgToplevelWindow(surface->surface())) {
             window->installPlasmaShellSurface(surface);
+        } else if (auto window = qobject_cast<LayerShellV1Window *>(findWindow(surface->surface()))) {
+            window->installPlasmaShellSurface(surface);
         }
     });
     m_appMenuManager = new AppMenuManagerInterface(m_display, m_display);
@@ -539,7 +550,7 @@ void WaylandServer::initWorkspace()

     auto layerShellV1Integration = new LayerShellV1Integration(this);
     connect(layerShellV1Integration, &LayerShellV1Integration::windowCreated,
-            this, &WaylandServer::registerWindow);
+            this, &WaylandServer::registerLayerShellWindow);

     if (environmentVariableBoolValue("KWIN_WAYLAND_SUPPORT_XX_PIP_V1").value_or(true)) {
         auto pipV1Integration = new XXPipV1Integration(this);
diff --git a/src/wayland_server.h b/src/wayland_server.h
index d99dac47a4..423a0287e4 100644
--- a/src/wayland_server.h
+++ b/src/wayland_server.h
@@ -238,6 +238,7 @@ Q_SIGNALS:
 private:
     int createScreenLockerConnection();
     void initScreenLocker();
+    void registerLayerShellWindow(Window *window);
     void registerXdgGenericWindow(Window *window);
     void registerXdgToplevelWindow(XdgToplevelWindow *window);
     void registerXdgPopupWindow(XdgPopupWindow *window);
-- 
