From 1aee007a4c00e7882d0c2ea98931af00ef482306 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 02:18:11 +0100
Subject: [PATCH] PlasmaShellWaylandIntegration: Expose the compositor's
 position

Layer shell windows can't know their position, so popups and tooltips of
panels were placed from a guess. Keep the position the compositor sends
for the surface and tell the window's owner when it changes.

CCBUG: 518087
---
 .../plasmashellwaylandintegration.cpp         | 30 +++++++++++++++++--
 .../plasmashellwaylandintegration.h           | 17 +++++++++++
 2 files changed, 44 insertions(+), 3 deletions(-)

diff --git a/src/plasmaquick/plasmashellwaylandintegration.cpp b/src/plasmaquick/plasmashellwaylandintegration.cpp
index c3af1b75c..1d42d7738 100644
--- a/src/plasmaquick/plasmashellwaylandintegration.cpp
+++ b/src/plasmaquick/plasmashellwaylandintegration.cpp
@@ -11,6 +11,8 @@
 #include <QWaylandClientExtensionTemplate>
 #include <QWindow>

+#include <functional>
+
 #include <qpa/qplatformwindow_p.h>

 #include <KWindowSystem>
@@ -19,7 +21,7 @@ class PlasmaShellManager : public QWaylandClientExtensionTemplate<PlasmaShellMan
 {
 public:
     PlasmaShellManager()
-        : QWaylandClientExtensionTemplate<PlasmaShellManager>(8)
+        : QWaylandClientExtensionTemplate<PlasmaShellManager>(9)
     {
         initialize();
     }
@@ -28,14 +30,24 @@ public:
 class PlasmaShellSurface : public QtWayland::org_kde_plasma_surface
 {
 public:
-    PlasmaShellSurface(struct ::org_kde_plasma_surface *impl)
+    PlasmaShellSurface(struct ::org_kde_plasma_surface *impl, std::function<void(const QPoint &)> positionHandler)
         : QtWayland::org_kde_plasma_surface(impl)
+        , m_positionHandler(std::move(positionHandler))
     {
     }
     ~PlasmaShellSurface()
     {
         destroy();
     }
+
+protected:
+    void org_kde_plasma_surface_position(int32_t x, int32_t y) override
+    {
+        m_positionHandler(QPoint(x, y));
+    }
+
+private:
+    std::function<void(const QPoint &)> m_positionHandler;
 };

 class WaylandIntegrationSingleton
@@ -67,6 +79,7 @@ public:
     PlasmaShellWaylandIntegration *q;
     QWindow *m_window = nullptr;
     std::optional<QPoint> m_position;
+    std::optional<QPoint> m_compositorPosition;
     QtWayland::org_kde_plasma_surface::panel_behavior m_panelBehavior = QtWayland::org_kde_plasma_surface::panel_behavior_always_visible;
     QtWayland::org_kde_plasma_surface::role m_role = QtWayland::org_kde_plasma_surface::role_normal;
     bool m_takesFocus = false;
@@ -108,7 +121,12 @@ void PlasmaShellWaylandIntegrationPrivate::surfaceCreated()
         return;
     }

-    m_shellSurface = std::make_unique<PlasmaShellSurface>(s_waylandIntegration->shellManager->get_surface(surface));
+    m_shellSurface = std::make_unique<PlasmaShellSurface>(s_waylandIntegration->shellManager->get_surface(surface), [this](const QPoint &position) {
+        if (position != m_compositorPosition) {
+            m_compositorPosition = position;
+            Q_EMIT q->compositorPositionChanged();
+        }
+    });
     if (m_shellSurface) {
         if (m_position) {
             m_shellSurface->set_position(m_position->x(), m_position->y());
@@ -127,6 +145,7 @@ void PlasmaShellWaylandIntegrationPrivate::surfaceCreated()
 void PlasmaShellWaylandIntegrationPrivate::surfaceDestroyed()
 {
     m_shellSurface.reset();
+    m_compositorPosition.reset();
 }

 PlasmaShellWaylandIntegration *PlasmaShellWaylandIntegration::get(QWindow *window)
@@ -228,4 +247,9 @@ void PlasmaShellWaylandIntegration::openUnderCursor()
     }
 }

+std::optional<QPoint> PlasmaShellWaylandIntegration::compositorPosition() const
+{
+    return d->m_compositorPosition;
+}
+
 #include "moc_plasmashellwaylandintegration.cpp"
diff --git a/src/plasmaquick/plasmashellwaylandintegration.h b/src/plasmaquick/plasmashellwaylandintegration.h
index 99e334e86..3e61308e8 100644
--- a/src/plasmaquick/plasmashellwaylandintegration.h
+++ b/src/plasmaquick/plasmashellwaylandintegration.h
@@ -10,6 +10,7 @@
 #include <QObject>
 #include <QPoint>
 #include <memory>
+#include <optional>

 #include "qwayland-plasma-shell.h"

@@ -68,8 +69,24 @@ public:
      */
     void openUnderCursor();

+    /*!
+     * The global position of this surface as last sent by the compositor, for surfaces
+     * that the compositor places itself, such as layer shell surfaces
+     *
+     * \since 6.9
+     */
+    std::optional<QPoint> compositorPosition() const;
+
     bool eventFilter(QObject *watched, QEvent *event) override;

+Q_SIGNALS:
+    /*!
+     * Emitted when the compositor sends a new position for this surface
+     *
+     * \since 6.9
+     */
+    void compositorPositionChanged();
+
 private:
     PlasmaShellWaylandIntegration(QWindow *window);

-- 
