From 80cc8eb34370af6c502929641b3de314402f8900 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 02:18:12 +0100
Subject: [PATCH] shell/panelview: Use the position the compositor sends for
 panels

Panels guessed their own position, and side panels assumed they started
at the top of the screen even below a top panel, so their tooltips and
popups opened shifted up by its height. Use the compositor's position.

BUG: 518087
---
 shell/panelview.cpp | 21 ++++++++++++++++++---
 shell/panelview.h   |  1 +
 2 files changed, 19 insertions(+), 3 deletions(-)

diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..42db93b235 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -33,6 +33,7 @@

 #include <Plasma/Containment>
 #include <PlasmaQuick/AppletQuickItem>
+#include <PlasmaQuick/PlasmaShellWaylandIntegration>

 #include <LayerShellQt/Window>

@@ -112,6 +113,11 @@ PanelView::PanelView(ShellCorona *corona, QScreen *targetScreen, QWindow *parent
         qCWarning(PLASMASHELL) << "Invalid home screen package";
     }

+    connect(PlasmaShellWaylandIntegration::get(this), &PlasmaShellWaylandIntegration::compositorPositionChanged, this, [this]() {
+        setPosition(panelPosition());
+        Q_EMIT geometryChanged();
+    });
+
     m_strutsTimer.setSingleShot(true);
     connect(&m_strutsTimer, &QTimer::timeout, this, &PanelView::updateExclusiveZone);

@@ -648,7 +654,7 @@ void PanelView::positionPanel()
     updateLayerWindow();

     // TODO: should we remove this? It's still relevant on wayland because of popup positioning.
-    const QPoint pos = geometryByDistance(0).topLeft();
+    const QPoint pos = panelPosition();
     setPosition(pos);
     updateMask();
     Q_EMIT geometryChanged();
@@ -673,7 +679,7 @@ void PanelView::positionAndResizePanel()
     }

     // TODO: can be removed? It's still relevant on wayland because of popup positioning.
-    const QPoint pos = geometryByDistance(0).topLeft();
+    const QPoint pos = panelPosition();

     const QRect geom = {pos, sizeHint};
     bool geomChanged = geom != geometry();
@@ -708,6 +714,15 @@ QRect PanelView::dogdeGeometryByDistance(int distance) const
     return dodgeGeometry & m_screenToFollow->geometry();
 }

+QPoint PanelView::panelPosition()
+{
+    // The compositor places the panel, so prefer the position it sends over our own guess
+    if (const auto position = PlasmaShellWaylandIntegration::get(this)->compositorPosition()) {
+        return *position;
+    }
+    return geometryByDistance(0).topLeft();
+}
+
 QRect PanelView::geometryByDistance(int distance) const
 {
     if (!containment() || !m_screenToFollow) {
@@ -1004,7 +1019,7 @@ void PanelView::resizeEvent(QResizeEvent *ev)
     if (m_screenToFollow && containment()) {
         updateEnabledBorders();
         // TODO: Can be removed? It's still relevant on wayland because of popup positioning.
-        const QPoint pos = geometryByDistance(0).topLeft();
+        const QPoint pos = panelPosition();
         setPosition(pos);
         Q_EMIT m_corona->availableScreenRegionChanged(containment()->screen());

diff --git a/shell/panelview.h b/shell/panelview.h
index eb276bf7f6..5fa8c84fff 100644
--- a/shell/panelview.h
+++ b/shell/panelview.h
@@ -317,6 +317,7 @@ private:
     void updateLayerWindow();
     void positionPanel();
     void positionAndResizePanel();
+    QPoint panelPosition();
     void updateThickness();
     void integrateScreen();
     void updateEditModeLabel();
-- 
